import { html, when, ref } from '../../@microsoft/fast-element/dist/esm/index.js';

const promptTemplate = () => html `
		<template
			role="complementary"
			aria-label="${(x) => x.ariaLabel}"
			aria-labelledby="${(x) => x.ariaLabelledby}"
			?disabled="${(x) => x.disabled}"
			?invalid="${(x) => x.invalid}"
			label="${(x) => (x.label ? x.label : null)}"
			instructional-text="${(x) => (x.instructionalText ? x.instructionalText : null)}"
			message="${(x) => x.validationMessage}"
			invalid="${(x) => x.invalid}"
			heading-label="${(x) => x.headingLabel}"
		>
			<div class="label-container" part="label-container">
				${when((x) => x.headingLabel, html `
						<div
							class="heading-label"
							part="heading-label"
							role="heading"
							aria-level="${(x) => x.headingLevel}"
						>
							${(x) => x.label}
						</div>
					`, html `
						<label
							part="label"
							class="label"
							aria-hidden="true"
							for="${(x) => x.inputId}"
						>
							${(x) => x.label}
						</label>
					`)}
				<p part="instructional-text" class="instructional-text">
					${(x) => x.instructionalText}
				</p>
			</div>
			<div class="wrapper" part="wrapper">
				<saf-text-area
					prompt-text-area
					${ref('textArea')}
					id="${(x) => x.inputId}"
					label="${(x) => x.label}"
					placeholder="${(x) => x.placeholderText}"
					instructional-text="${(x) => x.instructionalText}"
					a11y-aria-description="${(x) => x.textareaAriaDescription}"
					:value="${(x) => x.value}"
					:ariaLabel="${(x) => x.textareaAriaLabel}"
					maxlength="${(x) => x.maxlength}"
					?show-remaining-text="${(x) => x.showRemainingText}"
					?disabled="${(x) => x.disabled}"
					resize="none"
					?invalid="${(x) => x.invalid}"
					validation-message="${(x) => x.validationMessage}"
					@input="${(x, c) => x.handleTextAreaInput(c.event)}"
					@change="${(x, c) => x.handleTextAreaChange(c.event)}"
				>
				</saf-text-area>

				<div part="actions-area" class="actions-area" aria-live="polite">
					<div part="actions" class="actions">
						<slot name="actions"></slot>
					</div>
					<div class="controls" part="controls">
						${when((x) => x.processing, html `
								<saf-button
									${ref('stopButton')}
									part="stop"
									class="stop"
									density="compact"
									icon-only
									appearance="secondary"
									a11y-aria-label="${(x) => x.stopAriaLabel}"
									?disabled="${(x) => x.disabled}"
									@click="${(x) => x.handleStopClick()}"
								>
									<saf-icon
										part="stop-icon"
										icon-name="stop"
										role="presentation"
									></saf-icon>
								</saf-button>
							`, html `
								<saf-button
									${ref('sendButton')}
									part="send"
									class="send"
									density="compact"
									icon-only
									appearance="primary"
									a11y-aria-label="${(x) => x.sendAriaLabel}"
									?disabled="${(x) => x.isSendDisabled}"
									@click="${(x) => x.handleSendClick()}"
								>
									<saf-icon
										part="send-icon"
										icon-name="paper-plane"
										role="presentation"
									></saf-icon>
								</saf-button>
							`)}
					</div>
				</div>
			</div>
			<div class="footer-container" part="footer-container">
				${when((x) => x.processing && !x.hideProcessingText, html `<saf-progress-text>${(x) => x.processingText}</saf-progress-text>`)}
				<!-- security-caption-->
				<div class="security-caption" part="security-caption">
					<slot name="security-caption"></slot>
				</div>
			</div>
		</template>
	`;

export { promptTemplate };
